import Link from "next/link";
import { Activity, ArrowLeft, Dumbbell, Flame, Scale, ShieldCheck, Sparkles } from "lucide-react";
import Card from "../components/ui/Card";
import BriefingConfidenceAnchor from "../components/briefings/BriefingConfidenceAnchor";
import EnergyBalanceChart from "../components/briefings/EnergyBalanceChart";
import { TrainingPerformanceHighlights, TrainingWatchList } from "../components/briefings/TrainingPerformanceHighlights";
import { BriefingFeatureCard, BriefingSectionHeading, CadenceBriefingHero } from "../components/briefings/CadenceBriefingPrimitives";

export default function MidweekBriefingScreen({ briefing }) {
  const { energyBalance: energy, training, activePhase: phase } = briefing;
  return <main className="app-surface min-h-screen overflow-x-hidden"><div className="mx-auto max-w-[393px] px-4 pb-32 pt-10">
    <Link className="mb-5 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-[var(--text-secondary)]" href="/briefings/review"><ArrowLeft size={18}/>Briefing History</Link>
    <CadenceBriefingHero body={briefing.hero.summary} confidence={briefing.goalConfidence&&<BriefingConfidenceAnchor confidence={briefing.goalConfidence} testId="midweek-confidence"/>} context={<p className="mt-5 text-xs font-extrabold text-[var(--primary)]">{briefing.activeGoal?.name}</p>} icon={Sparkles} label="Midweek Briefing" labelDetail={briefing.preview&&<p className="text-[9px] font-bold uppercase tracking-[.08em] text-[var(--text-muted)]">Preview</p>} meta={<p className="text-right text-[10px] font-bold text-[var(--text-secondary)]">Sun–Tue<br/>{formatRange(briefing.evidenceWindow)}</p>} testId="midweek-hero" title={briefing.hero.verdict}>{phase && <div className="mt-4 flex flex-wrap gap-x-4 gap-y-1 border-t border-[var(--divider)] pt-3 text-[10px] font-bold text-[var(--text-secondary)]"><span>Current strategy: {phase.name}</span><span>{phase.weekLabel}</span><span>Review {shortDate(phase.plannedReviewDate)}</span></div>}</CadenceBriefingHero>
    <div className="mt-3 space-y-3">
      <BriefingFeatureCard icon={Flame} label="Energy Balance" tone="effort" title={energyConclusion(energy)}><p className="text-[26px] font-black leading-8 text-[var(--text-primary)]">{balanceHeadline(energy)}</p><p className="mt-3 text-sm font-semibold leading-6 text-[var(--text-secondary)]">{energyInterpretation(energy)}</p>{energy.comparison&&<p className="mt-2 text-xs font-semibold leading-5 text-[var(--text-muted)]">{energyComparisonText(energy)}</p>}<div className="mt-4 space-y-2">{energy.chartPoints.map((point)=><EnergyDay key={point.date} point={point}/>)}</div>{briefing.charts.energy&&<EnergyBalanceChart chart={briefing.charts.energy}/>}</BriefingFeatureCard>
      <Card><BriefingSectionHeading icon={Scale}>Weight Context</BriefingSectionHeading><p className="mt-2 text-2xl font-black">{value(briefing.weightContext.averageWeight," lb")}</p><p className="text-[10px] font-bold text-[var(--text-muted)]">Sunday–Tuesday average · {briefing.weightContext.observations} observations</p><p className="mt-3 text-sm font-semibold leading-6 text-[var(--text-secondary)]">{briefing.weightContext.interpretation}</p></Card>
      <BriefingFeatureCard icon={Dumbbell} label="Training Response" tone="primary" title={training.performanceHeadline}><p className="text-sm font-semibold leading-6 text-[var(--text-secondary)]">{training.interpretation}</p><TrainingPerformanceHighlights items={training.highlights}/><TrainingWatchList items={training.watch}/>{training.prioritySignals.length>0&&<div className="mt-5"><p className="text-[10px] font-black uppercase tracking-[.08em] text-[var(--text-muted)]">🎯 Priority Muscle Groups</p><div className="mt-2 grid gap-2">{training.prioritySignals.map((signal)=><PrioritySignal key={signal.key} signal={signal}/>)}</div></div>}</BriefingFeatureCard>
      <BodyComposition briefing={briefing}/>
      <section className="coach-take-card rounded-[24px] border border-white/10 bg-[color-mix(in_srgb,var(--primary)_82%,#171225)] p-5 text-white shadow-[0_18px_48px_rgba(12,8,28,.18)]" data-testid="coach-take"><p className="text-[10px] font-black uppercase tracking-[.12em] text-white/65">Coach&apos;s Take</p><CoachPoint emoji="💡" label="Biggest Takeaway">{coachOpinion(briefing)}</CoachPoint><CoachPoint emoji="🧠" label="My Recommendation" separated>{coachRecommendation(briefing)}</CoachPoint><div className="mt-7 border-t border-white/10 pt-5"><p className="text-[10px] font-black uppercase tracking-[.08em]"><span aria-hidden="true">🎯</span>{" "}<span className="text-white/70">Through Sunday</span></p><ol className="mt-3 space-y-3">{briefing.prioritiesThroughSunday.map((priority,index)=><li className="grid grid-cols-[1.25rem_1fr] items-start gap-2 text-sm font-semibold leading-6 text-white/90" key={priority}><span className="pt-px text-center font-black text-white/50">{index+1}</span><span>{priority}</span></li>)}</ol></div></section>
    </div>
  </div></main>;
}

function EnergyDay({point}) { return <div className="flex items-center justify-between gap-3 rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-xs font-black">{longDay(point.date)}</p><div className="text-right"><p className="text-[9px] font-bold uppercase tracking-[.08em] text-[var(--text-muted)]">{point.complete?"Energy Balance":""}</p><p className={`text-xs font-black ${point.complete?"text-[var(--text-primary)]":"text-[var(--text-muted)]"}`}>{point.complete?signedKcal(point.balance):"No data logged"}</p></div></div>; }
function MiniMetric({label,value:display}) { return <div className="min-w-0 rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-[9px] font-extrabold uppercase tracking-[.07em] text-[var(--text-muted)]">{label}</p><p className="mt-1 break-words text-xs font-black leading-5 text-[var(--text-primary)]">{display??"Unavailable"}</p></div>; }
function PrioritySignal({signal}) { const dot=signal.tone==="positive"?"🟢":signal.tone==="watch"?"🟠":"🟡"; return <div className="rounded-xl bg-[var(--surface-muted)] p-3"><p className="text-xs font-black">{dot} {signal.label}</p><p className="mt-1 text-[10px] font-bold leading-4 text-[var(--text-secondary)]">{signal.status}</p></div>; }
function BodyComposition({briefing}) { const body=briefing.bodyComposition,metrics=body?.newScan?body:body?.baseline; return <BriefingFeatureCard icon={body?.newScan?Activity:ShieldCheck} label="Body Composition" tone="evidence" title="Current Baseline">{metrics&&<div className="grid grid-cols-2 gap-2"><MiniMetric label="Body fat" value={value(metrics.bodyFatPercentage,"%")}/><MiniMetric label="Lean mass" value={value(metrics.leanMass," lb")}/><MiniMetric label="Fat mass" value={value(metrics.fatMass," lb")}/><MiniMetric label="DEXA date" value={longDate(metrics.date)}/></div>}<p className="mt-3 text-sm font-semibold leading-6 text-[var(--text-secondary)]">{body?.interpretation}</p><p className="mt-3 text-xs font-extrabold text-[var(--text-primary)]">Current objective: {body?.objective}</p></BriefingFeatureCard>; }
function CoachPoint({emoji,label,children,separated=false}) { return <div className={separated?"mt-7 border-t border-white/10 pt-5":"mt-5"}><p className="text-[10px] font-black uppercase tracking-[.08em]"><span aria-hidden="true">{emoji}</span>{" "}<span className="text-white/70">{label}</span></p><p className="mt-2 text-sm font-semibold leading-6 text-white/90">{children}</p></div>; }
function energyConclusion(energy) { return ({probably_below:"Intake is below estimated expenditure",probably_above:"Intake is above estimated expenditure",roughly_at:"Intake and expenditure are close",unclear:"More food and activity data needed"})[energy.balanceDirection]; }
function balanceHeadline(energy) { const amount=Math.abs(Math.round(energy.estimatedDailyBalanceMidpoint)); if(!Number.isFinite(amount))return "No daily estimate yet"; if(amount<25)return "About even day to day"; return `${amount.toLocaleString("en-US")} kcal/day ${energy.estimatedDailyBalanceMidpoint<0?"below":"above"}`; }
function energyInterpretation(energy) { const complete=energy.chartPoints.filter((point)=>point.complete), missing=energy.chartPoints.filter((point)=>!point.complete); if(!complete.length)return "Food or activity is missing for each day so far. Keep the plan steady and fill in what you can before Sunday."; const days=complete.map((point)=>longDay(point.date)); const dayText=days.length===1?days[0]:days.length===2?`${days[0]} and ${days[1]}`:`${days[0]}, ${days[1]}, and ${days[2]}`; const missingText=missing.length?` ${longDay(missing[0].date)} is missing data, which is another reason to wait for Sunday’s review.`:""; return energy.balanceDirection==="probably_below"?`${dayText} ${days.length===1?"suggests":"suggest"} you’re still below maintenance.${missingText} Keep calories steady for now.`:`${dayText} look close to maintenance.${missingText} Keep calories steady for now.`; }
function energyComparisonText(energy) { const previous=energy.comparison?.averageBalance,current=energy.estimatedAverageDailyBalance;if(!Number.isFinite(previous)||!Number.isFinite(current))return "The prior comparable period does not have enough paired evidence for a directional comparison.";const change=Math.round(current-previous);const direction=Math.abs(change)<25?"was similar to":change>0?"was higher than":"was lower than";const rmr=energy.rmrProvenance?.sourceDexaDate?` Estimated expenditure uses the DEXA RMR available on ${shortDate(energy.rmrProvenance.sourceDexaDate)} plus active calories.`:" Estimated expenditure is limited because an eligible RMR source is unavailable.";return `Average estimated balance ${direction} the prior comparable period by ${Math.abs(change).toLocaleString("en-US")} kcal/day.${rmr}`; }
function coachOpinion(briefing) { if(briefing.coachTake?.biggestTakeaway)return briefing.coachTake.biggestTakeaway; const top=briefing.training.highlights[0]; if(top)return `Training is progressing the way we want at the start of a lean-mass goal, led by ${top.exercise}. I would rather protect that momentum than react to a few days of calorie math.`; return "The important thing this week is establishing a training rhythm we can build on. There is nothing here that calls for an early change."; }
function coachRecommendation(briefing) { if(briefing.coachTake?.recommendation)return briefing.coachTake.recommendation; const missing=briefing.energyBalance.chartPoints.filter((point)=>!point.complete).map((point)=>longDay(point.date)); if(missing.length)return `${missing.join(" and ")} ${missing.length===1?"is":"are"} still incomplete. I’d make the calorie decision after a few more days with food and activity recorded instead of guessing today.`; return "Keep calories and activity steady through Sunday. If training continues to progress while weight remains controlled, we will have a stronger case for staying the course."; }
function signedKcal(number) { return `${number>0?"+":"−"}${Math.abs(Math.round(number)).toLocaleString("en-US")} kcal`; }
function value(number,suffix) { return Number.isFinite(number)?`${Number(number).toLocaleString("en-US",{maximumFractionDigits:1})}${suffix}`:"Unavailable"; }
function shortDate(value) { return value?new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`)):"Not established"; }
function longDate(value) { return value?new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",year:"numeric",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`)):"Unavailable"; }
function longDay(value) { return new Intl.DateTimeFormat("en-US",{weekday:"long",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`)); }
function formatRange(window) { return `${shortDate(window.startDate)}–${shortDate(window.endDate)}`; }
